{
  "scenes": [
    {
      "scene_id": "ep1-scene1",
      "lines": [
        {
          "kind": "sfx",
          "speaker_role_id": null,
          "text": "刺耳电流爆音，设备冒烟滋滋声，重物砸地闷响",
          "audio_cue_ref": "sfx_short_circuit_burst",
          "performance_hint": "突发、刺耳，瞬间拉高紧张感",
          "line_id": "ep1-s1-l1"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎！怎么又冒烟了！林岚，暴雨马上就来，街坊们还等着听预警，能不能先强行推闸？",
          "audio_cue_ref": "sfx_rain_background",
          "performance_hint": "焦急、语速快，带着迫切的责任感；哎！后留0.2秒气口接急促陈述，避免破音",
          "line_id": "ep1-s1-l2"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "先别动闸。过来，一起看设备状态。电源接头进水，强行推闸会烧毁主板。",
          "audio_cue_ref": null,
          "performance_hint": "冷静、干脆，不容置疑；句首短促制止，随后语气平稳陈述技术后果，指引对方靠近。",
          "line_id": "ep1-s1-l3"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "可这水迹……不会是哪个熊孩子故意泼水搞破坏吧？我这就去查监控！",
          "audio_cue_ref": "sfx_footsteps_rush",
          "performance_hint": "多疑、急躁，试图用假设掩盖无措；水迹处做轻微吸气停顿，模拟思绪转折，随后语流加速",
          "line_id": "ep1-s1-l4"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "站住。拿手电筒照准电源接头，我们先核对渗水位置和胶圈状态，再决定下一步。",
          "audio_cue_ref": "sfx_flashlight_click",
          "performance_hint": "严厉打断，祈使句，确立主导权；指令清晰，强调共同核对与谨慎决策。",
          "line_id": "ep1-s1-l5"
        }
      ]
    }
  ],
  "episode_summary": "本集聚焦于广播站电源故障的初步排查与两人的初次拉扯。林岚没有直接反驳周野的急躁，而是邀请他共同核对设备状态，用专业数据打破了周野关于人为破坏的无理猜疑，确立了维修主导权。两人在共同核对图纸与使用旧工具箱的过程中，触及了过去的旧伤，关系在默契配合中微妙缓和。结尾处水管破裂导致二次短路，验收被迫中断。",
  "fact_delta": [
    {
      "fact": "广播站电源接头进水短路",
      "status": "confirmed"
    },
    {
      "fact": "故障原因为防水胶圈老化碎裂导致的自然渗水，排除人为破坏",
      "status": "confirmed"
    },
    {
      "fact": "林岚留下的旧工具箱内有匹配规格的防水胶带",
      "status": "confirmed"
    },
    {
      "fact": "头顶老旧水管破裂导致二次短路",
      "status": "confirmed"
    }
  ],
  "relationship_delta": [
    {
      "from": "周野对林岚的急躁与猜疑",
      "to": "周野承认错怪林岚并表达愧疚",
      "status": "changed"
    },
    {
      "from": "林岚对周野的公事公办与防备",
      "to": "林岚邀请周野共同核对设备、递抹布并接纳旧工具，态度微妙缓和",
      "status": "changed"
    }
  ],
  "new_open_threads": [
    "两人约定广播恢复验收后敲三声铃报平安，但因二次短路尚未兑现",
    "二次进水后的抢修与外部天线验收任务"
  ],
  "closed_threads": []
}
